<script setup>
import {shallowRef,ref,onBeforeUnmount} from 'vue';
import {Button,Cell,Popup,Picker} from 'vant';
import 'vant/es/button/style';import 'vant/es/cell/style';import 'vant/es/popup/style';import 'vant/es/picker/style';
import StudentGradedAnswer from './StudentGradedAnswer.vue';
const props=defineProps({api:Function,paper:Object,question:Object,studentId:[Number,String],active:Function});
const c=window.GrowingStudentPaperAI.create(props),m=shallowRef(c.snapshot()),a=c.actions,unsub=c.subscribe(v=>m.value=v),types=[{value:'unknown',text:'待核对'},{value:'choice',text:'选择题'},{value:'fill',text:'填空题'},{value:'written',text:'解答题'}],typeOpen=ref(false),original=ref(false),uid='paper-ai-'+props.question.id+'-'+Math.random().toString(36).slice(2),failed=ref({});
onBeforeUnmount(()=>{unsub();c.destroy();});
function choose({selectedValues}){typeOpen.value=false;a.questionType(selectedValues[0]);}
</script>
<template><section class="student-paper-ai"><div class="paper-ai-actions"><Button :aria-expanded="m.solve.open" :aria-controls="uid+'-solve'" @click="a.toggle('solve')">AI解答</Button><Button v-if="!['choice','fill'].includes(m.questionType)" :disabled="m.questionType!=='written'" :aria-expanded="m.review.open" :aria-controls="uid+'-review'" @click="a.toggle('review')">AI批改</Button></div><Cell title="题型" :value="types.find(t=>t.value===m.questionType)?.text" is-link :clickable="!m.typeBusy" @click="!m.typeBusy&&(typeOpen=true)"/><p v-if="m.questionType==='unknown'">请对照原卷核对题型；解答题可使用 AI批改。</p><p role="status">{{m.status}}</p><Button class="paper-original-toggle" icon="play" :aria-expanded="original" :aria-controls="uid+'-original'" @click="original=!original">原卷作答</Button><section v-if="original" :id="uid+'-original'" aria-label="原卷作答"><figure v-for="page in m.originals" :key="page.page"><p v-if="page.missing||failed[page.page]" class="warning">第 {{page.page}} 页原卷缺失或无法加载，请补回照片。</p><img v-else :src="page.image" :alt="'第 '+page.page+' 页原卷，第 '+question.number+' 题'" @error="failed[page.page]=true"/><figcaption>第 {{page.page}} 页 · 第 {{question.number}} 题</figcaption></figure></section><section v-for="kind in ['solve','review']" v-show="m[kind].open" :id="uid+'-'+kind" :key="kind" :aria-label="kind==='solve'?'AI解答':'AI批改'"><header><h4>{{kind==='solve'?'AI解答':'AI批改'}}</h4><Button icon="cross" :aria-label="'关闭'+(kind==='solve'?'AI解答':'AI批改')" @click="a.toggle(kind)"/></header><p role="status" aria-live="polite">{{m[kind].status}}</p><div v-if="kind==='solve'&&m.solve.result!==null" class="math-prose" v-html="m.solutionHtml(m.solve.result)"/><StudentGradedAnswer v-if="kind==='review'&&m.review.result" :grade="{id:'paper-original-'+question.id,kind:'initial',result:{...m.review.result,answerPages:m.originals.filter(p=>!p.missing).map(p=>p.image)}}" :question="question" :paper="{pages:[]}" :render="m.render" grading-only/><Button v-if="m[kind].busy" @click="a.cancel(kind)">取消请求</Button><Button v-else-if="m[kind].status" @click="a.retry(kind)">重试</Button></section><Popup v-model:show="typeOpen" position="bottom" round><header><h3>核对题型</h3><Button icon="cross" aria-label="关闭题型选择" @click="typeOpen=false"/></header><Picker :columns="types" :model-value="[m.questionType]" @confirm="choose"><template #cancel><Button icon="cross" aria-label="关闭题型选择" @click="typeOpen=false"/></template></Picker></Popup></section></template>
<style scoped>.student-paper-ai{margin:16px 0;min-width:0}.paper-ai-actions,header{display:flex;gap:10px;align-items:center;flex-wrap:wrap}header{justify-content:space-between}header .van-button{width:44px;padding:0}.student-paper-ai.student-paper-ai :deep(.van-button){min-height:44px}.student-paper-ai img{max-width:100%;height:auto}.student-paper-ai figure{margin:14px 0}.student-paper-ai figcaption{font-size:13px;color:#66766a}.student-paper-ai section{margin:12px 0}.math-prose{white-space:pre-wrap;line-height:1.9;overflow-wrap:anywhere}.math-prose :deep(.katex-display){overflow-x:auto}.warning{color:#b42318}</style>

<style scoped>
/* visual-restore-legacy */
.student-paper-ai{margin:12px 0;color:#263c30;font:inherit}.paper-ai-actions{gap:10px;margin:0 0 12px}.student-paper-ai.student-paper-ai :deep(.van-button){height:auto;min-height:44px;padding:8px 12px;border:1px solid #bbc8ae;border-radius:8px;background:#f0f4eb;color:#263c30;font:inherit}.student-paper-ai.student-paper-ai :deep(.van-cell){display:block;width:max-content;max-width:100%;padding:0;background:transparent;font-size:.85em}.student-paper-ai.student-paper-ai :deep(.van-cell__value){display:block;min-height:44px;margin-top:6px;padding:9px 30px 9px 12px;border:1px solid #bbc8ae;border-radius:8px;background:#f0f4eb;text-align:left;color:#263c30}.student-paper-ai.student-paper-ai :deep(.van-cell__right-icon){position:absolute;right:10px;bottom:10px}.student-paper-ai.student-paper-ai :deep(.van-cell:after){display:none}.student-paper-ai>section{border:1px solid #d9e0d2;border-radius:12px;padding:14px;margin-top:12px;overflow-wrap:anywhere}.student-paper-ai>section>header h4{margin:0}.student-paper-ai figure{margin:12px 0}.student-paper-ai header :deep(.van-button){width:44px;padding:0}.student-paper-ai>.paper-original-toggle.van-button{display:block;margin:12px 0;padding:0;border:0;background:transparent;font-size:15px;text-align:left}
</style>
